VIEWS=[('n8rooms', "(()=>{const out=[];for(const k of Object.keys(DROOM)){const R=DROOM[k],must=(R.must||[])[0]||[R.items[0]];const t=must[0],F=FURN[t];if(!F){out.push([k,'no F',t]);continue;}const a={x:0,z:-CLD+F.d/2+.02,w:F.w,d:F.d};const t2=R.items.find(q=>FURN[q]&&!FURN[q].flat&&q!==t)||t,F2=FURN[t2];const b={x:-CLW+F2.w/2+.02,z:0,w:F2.d,d:F2.w};const ov=Math.abs(a.x-b.x)<(a.w+b.w)/2&&Math.abs(a.z-b.z)<(a.d+b.d)/2;out.push([k,t,[+a.x.toFixed(2),+a.z.toFixed(2)],t2,[+b.x.toFixed(2),+b.z.toFixed(2)],ov,CLW,CLD]);}return out;})()")]
